//! Release fuzz campaign (2026-11-21), oracle L4, a harness false positive.
//! w0 panicked in a handler; during its `stopped()` the system shutdown's
//! untrapped `Shutdown` signal replaced the reason (semantics.md L4,
//! `Lifecycle!LateSignalWins`), so it published `Shutdown(None)`. The oracle
//! excuses exactly that for a non-trapping actor, but it read the trap flag
//! from the driver's later `trap_exit(true)` on the already-exited w0, an
//! inert call. A trap flag set on an exiting or exited actor is now unknown.
//!
//! Generated by `cargo run --example repro -- <input> --emit untrapped_shutdown_after_late_trap`.
//!
//! Failure: none (passing input)
//! Strategy dfs:bound=0, seed 8169344594216460448.
//!
//! ```text
//! Scenario {
//!     seed: 8169344594216460448,
//!     sched: Canonical,
//!     ops: [
//!         Spawn {
//!             how: Managed {
//!                 group: 103,
//!             },
//!             hooks: Hooks {
//!                 flags: 53,
//!                 started_sleep: 101,
//!                 stopped_sleep: 202,
//!             },
//!         },
//!         Fence,
//!         Fence,
//!         TrapExit {
//!             who: 88,
//!             on: false,
//!         },
//!         Spawn {
//!             how: Managed {
//!                 group: 48,
//!             },
//!             hooks: Hooks {
//!                 flags: 101,
//!                 started_sleep: 202,
//!                 stopped_sleep: 0,
//!             },
//!         },
//!         Spawn {
//!             how: Linked {
//!                 parent: 33,
//!             },
//!             hooks: Hooks {
//!                 flags: 33,
//!                 started_sleep: 33,
//!                 stopped_sleep: 33,
//!             },
//!         },
//!         Request {
//!             to: 33,
//!             cmd: Panic,
//!             timeout: Some(
//!                 8481,
//!             ),
//!             detached: true,
//!         },
//!         Request {
//!             to: 33,
//!             cmd: Note(
//!                 105,
//!             ),
//!             timeout: None,
//!             detached: true,
//!         },
//!         ShutdownSystem {
//!             sys: 0,
//!             mode: 60,
//!             ms: 16501,
//!         },
//!         Monitor {
//!             watcher: 64,
//!             target: 240,
//!         },
//!         Monitor {
//!             watcher: 64,
//!             target: 0,
//!         },
//!         TrapExit {
//!             who: 0,
//!             on: true,
//!         },
//!         Fence,
//!         Fence,
//!         Fence,
//!         Fence,
//!         Fence,
//!         Spawn {
//!             how: Unmanaged,
//!             hooks: Hooks {
//!                 flags: 255,
//!                 started_sleep: 255,
//!                 stopped_sleep: 255,
//!             },
//!         },
//!         Spawn {
//!             how: Unmanaged,
//!             hooks: Hooks {
//!                 flags: 0,
//!                 started_sleep: 255,
//!                 stopped_sleep: 136,
//!             },
//!         },
//!         DropSystem {
//!             sys: 255,
//!         },
//!         Fence,
//!     ],
//! }
//! ```
#![cfg(spawned_sim)]

const INPUT: &[u8] = include_bytes!("../regressions/untrapped_shutdown_after_late_trap.input");

/// The input under its own schedule and under its recorded tape.
#[test]
fn untrapped_shutdown_after_late_trap_tape() {
    spawned_fuzz::assert_passes(INPUT, None);
}

/// The same operations under other simulator schedules.
#[spawned_macros::sim_test(seeds = 32)]
async fn untrapped_shutdown_after_late_trap_seeds(seed: u64) {
    spawned_fuzz::init();
    spawned_fuzz::run_body(spawned_fuzz::decode(INPUT).unwrap(), seed).await;
}
